import pandas as pd
from collections import defaultdict

def friends_with_no_mutual_friends(friends: pd.DataFrame) -> pd.DataFrame:
    adj = defaultdict(set)
    for _, row in friends.iterrows():
        u1, u2 = int(row['user_id1']), int(row['user_id2'])
        adj[u1].add(u2)
        adj[u2].add(u1)

    res = []
    for _, row in friends.iterrows():
        u1, u2 = int(row['user_id1']), int(row['user_id2'])
        if len(adj[u1].intersection(adj[u2])) == 0:
            res.append({'user_id1': u1, 'user_id2': u2})

    ans = pd.DataFrame(res)
    if ans.empty:
        return pd.DataFrame(columns=['user_id1', 'user_id2'])
    return ans.sort_values(by=['user_id1', 'user_id2'])
